import { type JSX, type SVGProps, useId } from "react";

/*
 * AI model makers' marks, inlined so the app never hotlinks: they show which company a model
 * name belongs to (model mapping). Nominative use only. Source: LobeHub icons,
 * `@lobehub/icons-static-svg` 1.102.0, MIT (see THIRD_PARTY_NOTICES.md). Generated from the
 * SVG files: titles dropped, gradient ids made unique per instance with useId. Marks with
 * one colour use currentColor, so they follow the theme.
 */

type MarkProps = Omit<SVGProps<SVGSVGElement>, "children" | "viewBox">;

export type ModelMaker =
  | "claude"
  | "openai"
  | "gemini"
  | "gemma"
  | "deepseek"
  | "grok"
  | "meta"
  | "mistral"
  | "qwen"
  | "kimi"
  | "zhipu"
  | "cohere"
  | "perplexity"
  | "minimax"
  | "microsoft"
  | "nova"
  | "doubao"
  | "hunyuan"
  | "wenxin"
  | "yi"
  | "openrouter";

